// Blender Geometry Nodes, first batch of Register rows (factory "flow", domain geometry_nodes): curve and mesh
// primitives, the measuring nodes (Domain Size, Bounding Box, Curve Length), and the string / switch / list utility
// nodes. Every node is registered under the category "Blender Geometry"; where a Grasshopper node already carries the
// Blender label the node here is named "<label> (Blender)" so neither replaces the other in the Registry.
//
// Oracles live in dino8-app/tests/sections/96_bf*.sh (generated by tests/flowrows3_gen.py) and are closed forms or exact
// counts written next to the expected value, never read back from this code.
//
// Data model notes (what a Flow value can and cannot say about a Blender geometry set):
//  * A curve is a degree-1 NURBS curve through the poly-spline points. A closed (cyclic) curve stores its first point a
//    second time at the end; "cyclic" is read back as "the last point equals the first".
//  * A mesh is an ON_Mesh (single precision vertices, triangles and quads). A Blender n-gon is a fan of triangles that
//    carries an ON_MeshNgon, so Domain Size can count it as one face. A mesh edge with no face (Mesh Line, an unfilled
//    Mesh Circle) is stored as a degenerate face (a, b, b, b); area and volume ignore it and Domain Size counts it as an edge.
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <utility>
#include <vector>

#include "flow/FlowBlenderCommon.h"

namespace dino8::flow {

namespace {

using namespace bl;

void AddCurvePrimitives() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Curve Line"; d.nick = "Line"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "A poly spline with two points. Mode 0 (Points): from Start to End. Mode 1 (Direction): from Start to Start + Direction (made unit length) * Length. A zero-length line is flagged.";
    d.inputs = {In("Mode", Kind::Integer, Access::Item, Value::Integer(0)), In("Start", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 0))),
                In("End", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 1))), In("Direction", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 1))),
                In("Length", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const Point3d a = c.Pt(1);
      Point3d b = c.Pt(2, Point3d(0, 0, 1));
      if (c.Int(0) == 1) {
        Vector3d dir = c.Vec(3, Vector3d(0, 0, 1));
        if (!dir.Unitize()) { c.Fail("Direction has zero length"); return; }
        b = a + dir * c.Num(4, 1);
      }
      if (a.DistanceTo(b) < 1e-12) { c.Fail("The line has zero length"); return; }
      c.Out(0, Value::Curve(PolyCurve({a, b}, false)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Curve Circle"; d.nick = "Circle"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "A closed poly spline with Resolution points on a circle of the given Radius in the XY plane, counter-clockwise, the first point at (Radius, 0, 0): point i is (r cos(2 pi i / n), r sin(2 pi i / n), 0). Resolution is limited to 3..10000.";
    d.inputs = {In("Resolution", Kind::Integer, Access::Item, Value::Integer(32)), In("Radius", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 32), 3, 10000);
      const double rad = c.Num(1, 1);
      std::vector<Point3d> pts;
      for (int i = 0; i < n; ++i) { const double t = 2.0 * kPi * i / n; pts.push_back(Point3d(rad * std::cos(t), rad * std::sin(t), 0)); }
      c.Out(0, Value::Curve(PolyCurve(pts, true)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Arc (Blender)"; d.nick = "BArc"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "An open poly spline of Resolution points on a circle of the given Radius in the XY plane, from Start Angle for Sweep Angle (radians, counter-clockwise when positive), both end points included: point i is at angle start + sweep * i / (n - 1). Resolution is limited to 2..10000.";
    d.inputs = {In("Resolution", Kind::Integer, Access::Item, Value::Integer(16)), In("Radius", Kind::Number, Access::Item, Value::Number(1)),
                In("Start Angle", Kind::Number, Access::Item, Value::Number(0)), In("Sweep Angle", Kind::Number, Access::Item, Value::Number(5.0 * kPi / 4.0))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 16), 2, 10000);
      const double rad = c.Num(1, 1), a0 = c.Num(2, 0), sw = c.Num(3, 5.0 * kPi / 4.0);
      std::vector<Point3d> pts;
      for (int i = 0; i < n; ++i) { const double t = a0 + sw * i / (n - 1); pts.push_back(Point3d(rad * std::cos(t), rad * std::sin(t), 0)); }
      c.Out(0, Value::Curve(PolyCurve(pts, false)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Quadrilateral"; d.nick = "Quad"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "A closed poly spline of four points, a Width x Height rectangle in the XY plane centred on the origin: (w/2, h/2), (-w/2, h/2), (-w/2, -h/2), (w/2, -h/2).";
    d.inputs = {In("Width", Kind::Number, Access::Item, Value::Number(2)), In("Height", Kind::Number, Access::Item, Value::Number(2))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const double w = c.Num(0, 2) / 2, h = c.Num(1, 2) / 2;
      if (std::fabs(w) < 1e-12 || std::fabs(h) < 1e-12) { c.Fail("Width and Height must not be zero"); return; }
      c.Out(0, Value::Curve(PolyCurve({Point3d(w, h, 0), Point3d(-w, h, 0), Point3d(-w, -h, 0), Point3d(w, -h, 0)}, true)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Quadratic Bezier"; d.nick = "QBez"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "An open poly spline sampling the quadratic Bezier curve through Start, Middle (control point) and End: Resolution edges, so Resolution + 1 points B(t) = (1-t)^2 Start + 2 t (1-t) Middle + t^2 End at t = i / Resolution. Resolution is limited to 1..10000.";
    d.inputs = {In("Resolution", Kind::Integer, Access::Item, Value::Integer(16)), In("Start", Kind::Point, Access::Item, Value::Point(Point3d(-1, 0, 0))),
                In("Middle", Kind::Point, Access::Item, Value::Point(Point3d(0, 2, 0))), In("End", Kind::Point, Access::Item, Value::Point(Point3d(1, 0, 0)))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 16), 1, 10000);
      const Point3d p0 = c.Pt(1, Point3d(-1, 0, 0)), p1 = c.Pt(2, Point3d(0, 2, 0)), p2 = c.Pt(3, Point3d(1, 0, 0));
      std::vector<Point3d> pts;
      for (int i = 0; i <= n; ++i) {
        const double t = static_cast<double>(i) / n, a = (1 - t) * (1 - t), b = 2 * t * (1 - t), e = t * t;
        pts.push_back(Point3d(a * p0.x + b * p1.x + e * p2.x, a * p0.y + b * p1.y + e * p2.y, a * p0.z + b * p1.z + e * p2.z));
      }
      c.Out(0, Value::Curve(PolyCurve(pts, false)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Star"; d.nick = "Star"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "A closed poly spline of 2 * Points vertices in the XY plane: outer vertices on Outer Radius at angles 2 pi i / Points, inner vertices on Inner Radius half a step later plus Twist (radians), alternating outer, inner. Points is limited to 3..10000.";
    d.inputs = {In("Points", Kind::Integer, Access::Item, Value::Integer(8)), In("Inner Radius", Kind::Number, Access::Item, Value::Number(1)),
                In("Outer Radius", Kind::Number, Access::Item, Value::Number(2)), In("Twist", Kind::Number, Access::Item, Value::Number(0))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 8), 3, 10000);
      const double ri = c.Num(1, 1), ro = c.Num(2, 2), tw = c.Num(3, 0);
      std::vector<Point3d> pts;
      for (int i = 0; i < n; ++i) {
        const double t = 2.0 * kPi * i / n, u = 2.0 * kPi * (i + 0.5) / n + tw;
        pts.push_back(Point3d(ro * std::cos(t), ro * std::sin(t), 0));
        pts.push_back(Point3d(ri * std::cos(u), ri * std::sin(u), 0));
      }
      c.Out(0, Value::Curve(PolyCurve(pts, true)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Spiral"; d.nick = "Spiral"; d.category = kCat; d.subcategory = "Curve Primitives";
    d.description = "An open poly spline winding around the Z axis: n = max(1, floor(Resolution * Rotations)) edges, point i at angle 2 pi Rotations i / n (clockwise when Reverse), radius Start Radius + (End Radius - Start Radius) i / n and height Height i / n.";
    d.inputs = {In("Resolution", Kind::Integer, Access::Item, Value::Integer(32)), In("Rotations", Kind::Number, Access::Item, Value::Number(2)),
                In("Start Radius", Kind::Number, Access::Item, Value::Number(1)), In("End Radius", Kind::Number, Access::Item, Value::Number(2)),
                In("Height", Kind::Number, Access::Item, Value::Number(2)), In("Reverse", Kind::Boolean, Access::Item, Value::Boolean(false))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      const int res = ClampInt(c.Int(0, 32), 1, 10000);
      const double rot = std::clamp(c.Num(1, 2), 0.0, 1000.0), r0 = c.Num(2, 1), r1 = c.Num(3, 2), h = c.Num(4, 2);
      const double sgn = c.Bool(5, false) ? -1.0 : 1.0;
      const int n = std::max(1, static_cast<int>(std::floor(res * rot)));
      std::vector<Point3d> pts;
      for (int i = 0; i <= n; ++i) {
        const double f = static_cast<double>(i) / n, t = sgn * 2.0 * kPi * rot * f, rad = r0 + (r1 - r0) * f;
        pts.push_back(Point3d(rad * std::cos(t), rad * std::sin(t), h * f));
      }
      if (pts[0].DistanceTo(pts[1]) < 1e-12) { c.Fail("The spiral has zero length"); return; }
      c.Out(0, Value::Curve(PolyCurve(pts, false)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Curve Length (Blender)"; d.nick = "BLen"; d.category = kCat; d.subcategory = "Curve";
    d.description = "The total length of the poly spline: the sum of its edge lengths, including the closing edge of a cyclic curve. A curve that is not degree 1 is measured on 256 samples.";
    d.inputs = {In("Curve", Kind::Curve)};
    d.outputs = {Out("Length", Kind::Number)};
    d.eval = [](EvalContext& c) {
      Poly p;
      if (!CurvePoly(c.In(0), p)) { c.Fail("Curve Length needs a curve"); return; }
      c.Out(0, Value::Number(PolyLength(p)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Subdivide Curve"; d.nick = "SubdCrv"; d.category = kCat; d.subcategory = "Curve";
    d.description = "Adds Cuts new points, evenly spaced, in every edge of the poly spline (the edge between the last and first point of a cyclic curve included). The original points stay. Cuts is limited to 0..1000.";
    d.inputs = {In("Curve", Kind::Curve), In("Cuts", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      Poly p;
      if (!CurvePoly(c.In(0), p)) { c.Fail("Subdivide Curve needs a curve"); return; }
      const int cuts = ClampInt(c.Int(1, 1), 0, 1000);
      std::vector<Point3d> out;
      const size_t segs = p.closed ? p.pts.size() : p.pts.size() - 1;
      for (size_t i = 0; i < segs; ++i) {
        const Point3d a = p.pts[i], b = p.pts[(i + 1) % p.pts.size()];
        for (int k = 0; k <= cuts; ++k) { const double t = static_cast<double>(k) / (cuts + 1); out.push_back(a + (b - a) * t); }
      }
      if (!p.closed) out.push_back(p.pts.back());
      c.Out(0, Value::Curve(PolyCurve(out, p.closed)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Resample Curve"; d.nick = "Resample"; d.category = kCat; d.subcategory = "Curve";
    d.description = "Count mode: replaces the poly spline with Count points evenly spaced by length. An open curve keeps both end points (spacing length / (Count - 1)); a cyclic curve starts at its first point (spacing length / Count). Count is limited to 1..100000 (2 and up for an open curve).";
    d.inputs = {In("Curve", Kind::Curve), In("Count", Kind::Integer, Access::Item, Value::Integer(10))};
    d.outputs = {Out("Curve", Kind::Curve)};
    d.eval = [](EvalContext& c) {
      Poly p;
      if (!CurvePoly(c.In(0), p)) { c.Fail("Resample Curve needs a curve"); return; }
      const int n = ClampInt(c.Int(1, 10), p.closed ? 3 : 2, 100000);
      const double total = PolyLength(p);
      if (!(total > 0)) { c.Fail("The curve has zero length"); return; }
      std::vector<Point3d> ring = p.pts;
      if (p.closed) ring.push_back(p.pts.front());
      std::vector<double> cum(ring.size(), 0.0);
      for (size_t i = 1; i < ring.size(); ++i) cum[i] = cum[i - 1] + ring[i - 1].DistanceTo(ring[i]);
      std::vector<Point3d> out;
      size_t seg = 0;
      for (int k = 0; k < n; ++k) {
        const double s = p.closed ? total * k / n : total * k / (n - 1);
        while (seg + 2 < ring.size() && cum[seg + 1] < s) ++seg;
        const double len = cum[seg + 1] - cum[seg];
        const double t = len > 0 ? std::clamp((s - cum[seg]) / len, 0.0, 1.0) : 0.0;
        out.push_back(ring[seg] + (ring[seg + 1] - ring[seg]) * t);
      }
      c.Out(0, Value::Curve(PolyCurve(out, p.closed)));
    };
    r.Add(d);
  }
}

// ------------------------------------------------------------------------------------------------------- mesh primitives

void AddMeshPrimitives() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Cube"; d.nick = "Cube"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A box centred on the origin with the given Size, subdivided into Vertices X / Y / Z lattice points along each axis (2 each gives the 8-vertex cube). Only the surface is meshed, quads facing outward: V = nx ny nz - (nx-2)(ny-2)(nz-2), F = 2((nx-1)(ny-1) + (ny-1)(nz-1) + (nx-1)(nz-1)). Each count is limited to 2..100.";
    d.inputs = {In("Size", Kind::Vector, Access::Item, Value::Vector(Vector3d(1, 1, 1))), In("Vertices X", Kind::Integer, Access::Item, Value::Integer(2)),
                In("Vertices Y", Kind::Integer, Access::Item, Value::Integer(2)), In("Vertices Z", Kind::Integer, Access::Item, Value::Integer(2))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const Vector3d sz = c.Vec(0, Vector3d(1, 1, 1));
      const int nx = ClampInt(c.Int(1, 2), 2, 100), ny = ClampInt(c.Int(2, 2), 2, 100), nz = ClampInt(c.Int(3, 2), 2, 100);
      MB mb;
      std::vector<int> id(static_cast<size_t>(nx) * ny * nz, -1);
      auto at = [&](int i, int j, int k) -> int& { return id[(static_cast<size_t>(k) * ny + j) * nx + i]; };
      auto vert = [&](int i, int j, int k) {
        int& slot = at(i, j, k);
        if (slot < 0) slot = mb.V((static_cast<double>(i) / (nx - 1) - 0.5) * sz.x, (static_cast<double>(j) / (ny - 1) - 0.5) * sz.y,
                                  (static_cast<double>(k) / (nz - 1) - 0.5) * sz.z);
        return slot;
      };
      // one lattice face: corners (a, b, c, d) counter-clockwise as seen from outside when `flip` is false
      auto quad = [&](int a, int b, int cc, int dd, bool flip) { if (flip) mb.Quad(a, dd, cc, b); else mb.Quad(a, b, cc, dd); };
      for (int j = 0; j + 1 < ny; ++j) for (int k = 0; k + 1 < nz; ++k) {      // -X and +X
        quad(vert(0, j, k), vert(0, j, k + 1), vert(0, j + 1, k + 1), vert(0, j + 1, k), false);
        quad(vert(nx - 1, j, k), vert(nx - 1, j + 1, k), vert(nx - 1, j + 1, k + 1), vert(nx - 1, j, k + 1), false);
      }
      for (int i = 0; i + 1 < nx; ++i) for (int k = 0; k + 1 < nz; ++k) {      // -Y and +Y
        quad(vert(i, 0, k), vert(i + 1, 0, k), vert(i + 1, 0, k + 1), vert(i, 0, k + 1), false);
        quad(vert(i, ny - 1, k), vert(i, ny - 1, k + 1), vert(i + 1, ny - 1, k + 1), vert(i + 1, ny - 1, k), false);
      }
      for (int i = 0; i + 1 < nx; ++i) for (int j = 0; j + 1 < ny; ++j) {      // -Z and +Z
        quad(vert(i, j, 0), vert(i, j + 1, 0), vert(i + 1, j + 1, 0), vert(i + 1, j, 0), false);
        quad(vert(i, j, nz - 1), vert(i + 1, j, nz - 1), vert(i + 1, j + 1, nz - 1), vert(i, j + 1, nz - 1), false);
      }
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Grid"; d.nick = "Grid"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A flat grid of quads in the XY plane centred on the origin, normal +Z: Vertices X x Vertices Y points over Size X x Size Y, (nx-1)(ny-1) faces. Each count is limited to 1..1000 (a count of 1 gives no faces).";
    d.inputs = {In("Size X", Kind::Number, Access::Item, Value::Number(1)), In("Size Y", Kind::Number, Access::Item, Value::Number(1)),
                In("Vertices X", Kind::Integer, Access::Item, Value::Integer(3)), In("Vertices Y", Kind::Integer, Access::Item, Value::Integer(3))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const double sx = c.Num(0, 1), sy = c.Num(1, 1);
      const int nx = ClampInt(c.Int(2, 3), 1, 1000), ny = ClampInt(c.Int(3, 3), 1, 1000);
      MB mb;
      for (int i = 0; i < nx; ++i) for (int j = 0; j < ny; ++j)
        mb.V(nx > 1 ? (static_cast<double>(i) / (nx - 1) - 0.5) * sx : 0.0, ny > 1 ? (static_cast<double>(j) / (ny - 1) - 0.5) * sy : 0.0, 0.0);
      auto vi = [&](int i, int j) { return i * ny + j; };
      for (int i = 0; i + 1 < nx; ++i) for (int j = 0; j + 1 < ny; ++j) mb.Quad(vi(i, j), vi(i + 1, j), vi(i + 1, j + 1), vi(i, j + 1));
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "UV Sphere"; d.nick = "UVSphere"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A sphere of the given Radius about the origin with its poles on the Z axis: Segments meridians and Rings latitude bands, V = Segments (Rings - 1) + 2 vertices, F = Segments Rings faces (triangles at the poles, quads between). Ring k lies at polar angle pi k / Rings. Segments is limited to 3..512, Rings to 2..512.";
    d.inputs = {In("Segments", Kind::Integer, Access::Item, Value::Integer(32)), In("Rings", Kind::Integer, Access::Item, Value::Integer(16)),
                In("Radius", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const int S = ClampInt(c.Int(0, 32), 3, 512), R = ClampInt(c.Int(1, 16), 2, 512);
      const double rad = c.Num(2, 1);
      MB mb;
      const int top = mb.V(0, 0, rad);
      std::vector<std::vector<int>> ring(static_cast<size_t>(R - 1));
      for (int k = 1; k < R; ++k) {
        const double phi = kPi * k / R;
        for (int j = 0; j < S; ++j) {
          const double th = 2.0 * kPi * j / S;
          ring[static_cast<size_t>(k - 1)].push_back(mb.V(rad * std::sin(phi) * std::cos(th), rad * std::sin(phi) * std::sin(th), rad * std::cos(phi)));
        }
      }
      const int bot = mb.V(0, 0, -rad);
      for (int j = 0; j < S; ++j) mb.Tri(top, ring[0][static_cast<size_t>(j)], ring[0][static_cast<size_t>((j + 1) % S)]);
      for (int k = 0; k + 1 < R - 1; ++k) for (int j = 0; j < S; ++j) {
        const int j1 = (j + 1) % S;
        mb.Quad(ring[static_cast<size_t>(k)][static_cast<size_t>(j)], ring[static_cast<size_t>(k + 1)][static_cast<size_t>(j)],
                ring[static_cast<size_t>(k + 1)][static_cast<size_t>(j1)], ring[static_cast<size_t>(k)][static_cast<size_t>(j1)]);
      }
      for (int j = 0; j < S; ++j) mb.Tri(bot, ring[static_cast<size_t>(R - 2)][static_cast<size_t>((j + 1) % S)], ring[static_cast<size_t>(R - 2)][static_cast<size_t>(j)]);
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
  // Cylinder and Cone share one builder: a frustum from radius_bottom at z = -depth/2 to radius_top at z = +depth/2.
  struct Frustum { int verts, side; double rtop, rbot, depth; int fill; };
  static auto build_frustum = [](const Frustum& f, std::string& why) -> kernel::Mesh {
    MB mb;
    const int n = f.verts;
    auto ring_at = [&](double rad, double z) {
      std::vector<int> ids;
      for (int j = 0; j < n; ++j) { const double t = 2.0 * kPi * j / n; ids.push_back(mb.V(rad * std::cos(t), rad * std::sin(t), z)); }
      return ids;
    };
    const double zb = -f.depth / 2, zt = f.depth / 2;
    // rows[0] is the bottom, rows[side] the top; a zero radius collapses a row to one apex vertex
    std::vector<std::vector<int>> rows;
    for (int s = 0; s <= f.side; ++s) {
      const double t = static_cast<double>(s) / f.side, rad = f.rbot + (f.rtop - f.rbot) * t, z = zb + (zt - zb) * t;
      if (rad == 0.0 && (s == 0 || s == f.side)) rows.push_back({mb.V(0, 0, z)});
      else rows.push_back(ring_at(rad, z));
    }
    for (int s = 0; s < f.side; ++s) {
      const std::vector<int>& lo = rows[static_cast<size_t>(s)];
      const std::vector<int>& hi = rows[static_cast<size_t>(s + 1)];
      for (int j = 0; j < n; ++j) {
        const int j1 = (j + 1) % n;
        if (lo.size() == 1) mb.Tri(lo[0], hi[static_cast<size_t>(j1)], hi[static_cast<size_t>(j)]);
        else if (hi.size() == 1) mb.Tri(lo[static_cast<size_t>(j)], lo[static_cast<size_t>(j1)], hi[0]);
        else mb.Quad(lo[static_cast<size_t>(j)], lo[static_cast<size_t>(j1)], hi[static_cast<size_t>(j1)], hi[static_cast<size_t>(j)]);
      }
    }
    // caps: fill 0 none, 1 n-gon, 2 triangle fan (cap rows that collapsed to an apex have none)
    auto cap = [&](const std::vector<int>& row, double z, bool up) {
      if (row.size() == 1 || f.fill == 0) return;
      std::vector<int> ring = row;
      if (!up) std::reverse(ring.begin(), ring.end());
      if (f.fill == 1) { mb.Ngon(ring); return; }
      const int ctr = mb.V(0, 0, z);
      for (int j = 0; j < n; ++j) mb.Tri(ctr, ring[static_cast<size_t>(j)], ring[static_cast<size_t>((j + 1) % n)]);
    };
    cap(rows.back(), zt, true);
    cap(rows.front(), zb, false);
    (void)why;
    return mb.Build();
  };
  {
    NodeDef d; d.name = "Cylinder"; d.nick = "Cylinder"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A cylinder about the Z axis from z = -Depth/2 to +Depth/2 with Vertices points per ring and Side Segments rows of quads. Fill Type 0 none, 1 n-gon (default; one face per cap), 2 triangle fan (adds a centre vertex per cap). Vertices is limited to 3..1000, Side Segments to 1..1000.";
    d.inputs = {In("Vertices", Kind::Integer, Access::Item, Value::Integer(32)), In("Side Segments", Kind::Integer, Access::Item, Value::Integer(1)),
                In("Radius", Kind::Number, Access::Item, Value::Number(1)), In("Depth", Kind::Number, Access::Item, Value::Number(2)),
                In("Fill Type", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      Frustum f{ClampInt(c.Int(0, 32), 3, 1000), ClampInt(c.Int(1, 1), 1, 1000), c.Num(2, 1), c.Num(2, 1), c.Num(3, 2), ClampInt(c.Int(4, 1), 0, 2)};
      if (!(f.rtop > 0) || !(f.depth != 0)) { c.Fail("Radius must be positive and Depth not zero"); return; }
      std::string why;
      c.Out(0, Value::MeshV(build_frustum(f, why)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Cone"; d.nick = "Cone"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A cone or frustum about the Z axis from z = -Depth/2 (Radius Bottom) to +Depth/2 (Radius Top). A radius of exactly 0 collapses that end to a single vertex and gives it no cap. Fill Type 0 none, 1 n-gon (default), 2 triangle fan. Vertices is limited to 3..1000, Side Segments to 1..1000; both radii zero is flagged.";
    d.inputs = {In("Vertices", Kind::Integer, Access::Item, Value::Integer(32)), In("Side Segments", Kind::Integer, Access::Item, Value::Integer(1)),
                In("Radius Top", Kind::Number, Access::Item, Value::Number(0)), In("Radius Bottom", Kind::Number, Access::Item, Value::Number(1)),
                In("Depth", Kind::Number, Access::Item, Value::Number(2)), In("Fill Type", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      Frustum f{ClampInt(c.Int(0, 32), 3, 1000), ClampInt(c.Int(1, 1), 1, 1000), std::max(0.0, c.Num(2, 0)), std::max(0.0, c.Num(3, 1)), c.Num(4, 2), ClampInt(c.Int(5, 1), 0, 2)};
      if (f.rtop == 0.0 && f.rbot == 0.0) { c.Fail("Both radii are zero"); return; }
      if (f.depth == 0.0) { c.Fail("Depth must not be zero"); return; }
      std::string why;
      c.Out(0, Value::MeshV(build_frustum(f, why)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Mesh Circle"; d.nick = "MCircle"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "Vertices points on a circle of the given Radius in the XY plane, counter-clockwise from (Radius, 0, 0). Fill Type 0 none (default; Vertices edges, no face), 1 n-gon (one face), 2 triangle fan (centre vertex, Vertices triangles). Vertices is limited to 3..10000.";
    d.inputs = {In("Vertices", Kind::Integer, Access::Item, Value::Integer(32)), In("Radius", Kind::Number, Access::Item, Value::Number(1)),
                In("Fill Type", Kind::Integer, Access::Item, Value::Integer(0))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 32), 3, 10000);
      const double rad = c.Num(1, 1);
      const int fill = ClampInt(c.Int(2, 0), 0, 2);
      MB mb;
      std::vector<int> ring;
      for (int j = 0; j < n; ++j) { const double t = 2.0 * kPi * j / n; ring.push_back(mb.V(rad * std::cos(t), rad * std::sin(t), 0)); }
      if (fill == 0) for (int j = 0; j < n; ++j) mb.Wire(ring[static_cast<size_t>(j)], ring[static_cast<size_t>((j + 1) % n)]);
      else if (fill == 1) mb.Ngon(ring);
      else { const int ctr = mb.V(0, 0, 0); for (int j = 0; j < n; ++j) mb.Tri(ctr, ring[static_cast<size_t>(j)], ring[static_cast<size_t>((j + 1) % n)]); }
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Mesh Line"; d.nick = "MLine"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "Count vertices joined by Count - 1 edges (no faces). Mode 0 (Offset): vertex i is Start + i * Offset. Mode 1 (End Points): the Offset input is the end location and vertex i is Start + (End - Start) i / (Count - 1). Count is limited to 1..100000.";
    d.inputs = {In("Count", Kind::Integer, Access::Item, Value::Integer(10)), In("Start Location", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 0))),
                In("Offset", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 1))), In("Mode", Kind::Integer, Access::Item, Value::Integer(0))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const int n = ClampInt(c.Int(0, 10), 1, 100000);
      const Point3d a = c.Pt(1);
      const Vector3d o = c.Vec(2, Vector3d(0, 0, 1));
      const bool ends = c.Int(3, 0) == 1;
      MB mb;
      for (int i = 0; i < n; ++i) {
        Point3d p = a;
        if (ends) { if (n > 1) p = a + (Point3d(o.x, o.y, o.z) - a) * (static_cast<double>(i) / (n - 1)); }
        else p = a + o * static_cast<double>(i);
        mb.V(p.x, p.y, p.z);
      }
      for (int i = 0; i + 1 < n; ++i) mb.Wire(i, i + 1);
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Ico Sphere"; d.nick = "IcoSphere"; d.category = kCat; d.subcategory = "Mesh Primitives";
    d.description = "A geodesic sphere of the given Radius: Subdivisions 1 is the icosahedron (12 vertices, 30 edges, 20 triangles, poles on the Z axis); every further level splits each triangle in four and pushes the new vertices onto the sphere, so F = 20 * 4^(s-1), V = 10 * 4^(s-1) + 2. Subdivisions is limited to 1..7.";
    d.inputs = {In("Radius", Kind::Number, Access::Item, Value::Number(1)), In("Subdivisions", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("Mesh", Kind::Mesh)};
    d.eval = [](EvalContext& c) {
      const double rad = c.Num(0, 1);
      const int sub = ClampInt(c.Int(1, 1), 1, 7);
      std::vector<Vector3d> v;
      std::vector<std::array<int, 3>> tris;
      const double zr = 1.0 / std::sqrt(5.0), rr = 2.0 / std::sqrt(5.0);
      v.push_back(Vector3d(0, 0, 1));
      for (int k = 0; k < 5; ++k) v.push_back(Vector3d(rr * std::cos(2.0 * kPi * k / 5), rr * std::sin(2.0 * kPi * k / 5), zr));
      for (int k = 0; k < 5; ++k) v.push_back(Vector3d(rr * std::cos(2.0 * kPi * (k + 0.5) / 5), rr * std::sin(2.0 * kPi * (k + 0.5) / 5), -zr));
      v.push_back(Vector3d(0, 0, -1));
      for (int k = 0; k < 5; ++k) {
        const int k1 = (k + 1) % 5;
        tris.push_back({0, 1 + k, 1 + k1});
        tris.push_back({1 + k, 6 + k, 1 + k1});
        tris.push_back({1 + k1, 6 + k, 6 + k1});
        tris.push_back({11, 6 + k1, 6 + k});
      }
      for (int s = 1; s < sub; ++s) {
        std::map<std::pair<int, int>, int> mid;
        auto midpoint = [&](int a, int b) {
          const std::pair<int, int> key{std::min(a, b), std::max(a, b)};
          auto it = mid.find(key);
          if (it != mid.end()) return it->second;
          Vector3d m = (v[static_cast<size_t>(a)] + v[static_cast<size_t>(b)]) * 0.5;
          m.Unitize();
          v.push_back(m);
          return mid[key] = static_cast<int>(v.size()) - 1;
        };
        std::vector<std::array<int, 3>> next;
        for (const auto& t : tris) {
          const int ab = midpoint(t[0], t[1]), bc = midpoint(t[1], t[2]), ca = midpoint(t[2], t[0]);
          next.push_back({t[0], ab, ca}); next.push_back({t[1], bc, ab}); next.push_back({t[2], ca, bc}); next.push_back({ab, bc, ca});
        }
        tris.swap(next);
      }
      MB mb;
      for (const Vector3d& p : v) mb.V(p.x * rad, p.y * rad, p.z * rad);
      for (const auto& t : tris) mb.Tri(t[0], t[1], t[2]);
      c.Out(0, Value::MeshV(mb.Build()));
    };
    r.Add(d);
  }
}

// ------------------------------------------------------------------------------------------------------- measuring

void AddMeasuring() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Domain Size"; d.nick = "DomSize"; d.category = kCat; d.subcategory = "Geometry";
    d.description = "Element counts of a geometry: for a mesh Point Count (vertices), Edge Count (distinct edges, an n-gon contributes its boundary edges, an edge with no face counts), Face Count (an n-gon is one face) and Face Corner Count (3 per triangle, 4 per quad, one per boundary edge of an n-gon); for a curve Point Count (a repeated closing point is not counted) and Spline Count 1. A point counts as one point.";
    d.inputs = {In("Geometry", Kind::Any)};
    d.outputs = {Out("Point Count", Kind::Integer), Out("Edge Count", Kind::Integer), Out("Face Count", Kind::Integer),
                 Out("Face Corner Count", Kind::Integer), Out("Spline Count", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const Value& g = c.In(0);
      long long pt = 0, ed = 0, fa = 0, co = 0, sp = 0;
      if (g.kind == Kind::Mesh && g.mesh) {
        const MeshCounts m = CountMesh(g.mesh->raw());
        pt = m.points; ed = m.edges; fa = m.faces; co = m.corners;
      } else if (g.kind == Kind::Curve) {
        Poly p;
        if (!CurvePoly(g, p)) { c.Fail("Domain Size could not read the curve"); return; }
        pt = static_cast<long long>(p.pts.size()); sp = 1;
      } else if (g.kind == Kind::Point) pt = 1;
      else { c.Fail("Domain Size needs a mesh, curve or point"); return; }
      c.Out(0, Value::Integer(pt)); c.Out(1, Value::Integer(ed)); c.Out(2, Value::Integer(fa));
      c.Out(3, Value::Integer(co)); c.Out(4, Value::Integer(sp));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Bounding Box"; d.nick = "BBox"; d.category = kCat; d.subcategory = "Geometry";
    d.description = "The axis-aligned box that contains every vertex of a mesh, every point of a poly-spline curve (256 samples for a smooth one), or a point: Min and Max corners. Mesh coordinates are single precision.";
    d.inputs = {In("Geometry", Kind::Any)};
    d.outputs = {Out("Min", Kind::Point), Out("Max", Kind::Point)};
    d.eval = [](EvalContext& c) {
      const Value& g = c.In(0);
      std::vector<Point3d> pts;
      if (g.kind == Kind::Mesh && g.mesh) {
        const ON_Mesh& m = g.mesh->raw();
        for (int i = 0; i < m.VertexCount(); ++i) pts.push_back(Point3d(m.m_V[i].x, m.m_V[i].y, m.m_V[i].z));
      } else if (g.kind == Kind::Curve) {
        Poly p;
        if (CurvePoly(g, p)) pts = p.pts;
      } else if (g.kind == Kind::Point) pts.push_back(g.point);
      if (pts.empty()) { c.Out(0, Value::Point(Point3d(0, 0, 0))); c.Out(1, Value::Point(Point3d(0, 0, 0))); return; }
      Point3d lo = pts[0], hi = pts[0];
      for (const Point3d& p : pts) { lo.x = std::min(lo.x, p.x); lo.y = std::min(lo.y, p.y); lo.z = std::min(lo.z, p.z); hi.x = std::max(hi.x, p.x); hi.y = std::max(hi.y, p.y); hi.z = std::max(hi.z, p.z); }
      c.Out(0, Value::Point(lo));
      c.Out(1, Value::Point(hi));
    };
    r.Add(d);
  }
}

// ------------------------------------------------------------------------------------------------------- utilities

void AddUtilities() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Join Strings"; d.nick = "JoinStr"; d.category = kCat; d.subcategory = "Text";
    d.description = "Concatenates the strings in the order they arrive with the Delimiter between neighbours (none before the first or after the last). No strings give the empty string.";
    d.inputs = {In("Delimiter", Kind::Text, Access::Item, Value::Text("")), In("Strings", Kind::Text, Access::List)};
    d.outputs = {Out("String", Kind::Text)};
    d.eval = [](EvalContext& c) {
      const std::string delim = c.Text(0);
      std::string out;
      bool first = true;
      for (const Value& v : c.List(1)) { if (!first) out += delim; out += v.AsText(); first = false; }
      c.Out(0, Value::Text(out));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Switch"; d.nick = "Switch"; d.category = kCat; d.subcategory = "Utilities";
    d.description = "Passes on the True input when Switch is true, the False input otherwise.";
    d.inputs = {In("Switch", Kind::Boolean, Access::Item, Value::Boolean(false)), In("False", Kind::Any, Access::Item, Value::Null(), true),
                In("True", Kind::Any, Access::Item, Value::Null(), true)};
    d.outputs = {Out("Output", Kind::Any)};
    d.eval = [](EvalContext& c) { const Value& v = c.Bool(0, false) ? c.In(2) : c.In(1); if (!v.IsNull()) c.Out(0, v); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Index Switch"; d.nick = "IdxSwitch"; d.category = kCat; d.subcategory = "Utilities";
    d.description = "Passes on the item whose position equals Index (0 to 3). An Index outside 0..3, or one that selects an empty item, gives the default value of the type of Item 0 (0, false, empty text, the origin).";
    d.inputs = {In("Index", Kind::Integer, Access::Item, Value::Integer(0)), In("Item 0", Kind::Any, Access::Item, Value::Null(), true),
                In("Item 1", Kind::Any, Access::Item, Value::Null(), true), In("Item 2", Kind::Any, Access::Item, Value::Null(), true),
                In("Item 3", Kind::Any, Access::Item, Value::Null(), true)};
    d.outputs = {Out("Output", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const int i = c.Int(0, 0);
      const Value& sel = (i >= 0 && i <= 3) ? c.In(1 + i) : c.In(0);
      if (i >= 0 && i <= 3 && !sel.IsNull()) { c.Out(0, sel); return; }
      const Value def = DefaultLike(c.In(1));
      if (!def.IsNull()) c.Out(0, def);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "List Length (Blender)"; d.nick = "BListLen"; d.category = kCat; d.subcategory = "List";
    d.description = "The number of items in the list.";
    d.inputs = {In("List", Kind::Any, Access::List)};
    d.outputs = {Out("Length", Kind::Integer)};
    d.eval = [](EvalContext& c) { c.Out(0, Value::Integer(static_cast<long long>(c.List(0).size()))); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Get List Item"; d.nick = "GetItem"; d.category = kCat; d.subcategory = "List";
    d.description = "The item at Index (0 is the first). An index outside the list gives the default value of the type of the list's first item (0 for an empty list).";
    d.inputs = {In("List", Kind::Any, Access::List), In("Index", Kind::Integer, Access::Item, Value::Integer(0))};
    d.outputs = {Out("Value", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const long long i = c.Int(1, 0);
      if (i >= 0 && i < static_cast<long long>(l.size())) { c.Out(0, l[static_cast<size_t>(i)]); return; }
      const Value def = l.empty() ? Value::Number(0) : DefaultLike(l[0]);
      if (!def.IsNull()) c.Out(0, def);
    };
    r.Add(d);
  }
}

}  // namespace

void RegisterBlenderNodes() {
  AddCurvePrimitives();
  AddMeshPrimitives();
  AddMeasuring();
  AddUtilities();
}

}  // namespace dino8::flow
